INSERT INTO `movie` VALUES ('27919400-3019-48fc-9899-fea3eddd299f','Zazie Beetz, Myha’La, Paterson Joseph, Tom Felton, Heather Graham, Patricia Arquette,...','2026-04-22 02:17:14.638513','Đến từ New Line Cinema và Nocturna, CHÚNG SẼ ĐOẠT MẠNG (tựa gốc: THEY WILL KILL YOU) là một tác phẩm kinh dị - hành động - hài hước đẫm máu và đầy kịch tính xoay quanh cuộc chiến sống còn của một người phụ nữ tại tòa nhà xa hoa The Virgil - hang ổ của một giáo phái ma quỷ. Khi màn đêm buông xuống, những cạm bẫy được giăng ra, kẻ không thể sống sót sẽ trở thành vật tế tiếp theo. Một trận chiến chết chóc mãn nhãn cùng phong cách hài đen đầy mê hoặc sẽ sớm bắt đầu trên màn ảnh rộng.','Kirill Sokolov',95,'http://res.cloudinary.com/dod2sfnsr/image/upload/c_fill,g_face,h_420,w_280/mt8gxlyfj0xxjmpsdby1','2026-03-27','NOW_SHOWING','CHÚNG SẼ ĐOẠT MẠNG','https://www.youtube.com/watch?v=WYdP2RCSgCI','2026-04-22 09:07:39.287854'),('36d812a4-9b74-4f38-ad31-df118d5d2646','','2026-04-22 06:32:49.493302','Theo truyền thống, khi tròn 13 tuổi, con gái của các phù thủy phải rời xa quê hương để học cách tự lập . Kiki cũng thế, cô lên đường cùng chú mèo đen Jiji, bay đến thị trấn ven biển Koriko xa lạ. Tại đây, cô được một bà chủ tiệm bánh tốt bụng cưu mang và bắt đầu làm phụ tá cho bà, đồng thời cũng bắt đầu mở dịch vụ giao hàng mới bằng chổi bay. Cuộc sống mới mang đến cho Kiki những niềm vui, thất bại và thử thách đầu đời. Xen giữa hành trình ấy là tình bạn với Tombo - cậu bé có đam mê mãnh liệt với máy bay chạy bằng sức người. Tất cả đã giúp Kiki từng bước trưởng thành và hòa nhập với thị trấn biển đầy gió này.',' Hayao Miyazaki',120,'http://res.cloudinary.com/dod2sfnsr/image/upload/c_fill,g_face,h_420,w_280/l41rpjrrratcgorknkav','2026-04-26','COMING_SOON','DỊCH VỤ GIAO HÀNG CỦA PHÙ THỦY KIKI','https://www.youtube.com/watch?v=NOViU0gVYvg','2026-04-22 06:36:17.201996'),('39ec896b-819c-4898-aa3a-d921d3b00003','Choi Woo-shik, Jang Hye-jin, Gong Seung-yeon','2026-04-22 01:50:47.007620','Đếm Ngày Xa Mẹ xoay quanh cặp mẹ con Eun-sil (Jang Hye-jin) và Ha-min (Choi Woo-shik). Mỗi lần ăn một món do mẹ nấu, Ha-min lại nhìn thấy một con số khó lý giải. Sau mỗi bữa ăn, con số ấy giảm đi một đơn vị. Ha-min sớm nhận ra một sự thật kinh hoàng: khi con số chạm về 0, mẹ anh sẽ qua đời. Kể từ đó, cuộc sống bình thường của Ha-min bị đảo lộn hoàn toàn. Để bảo vệ quãng thời gian còn lại của mẹ, Ha-min bắt đầu tránh xa những bữa cơm nhà, viện đủ mọi lý do để không phải ngồi vào bàn ăn và dần trở nên xa cách với mẹ. Liệu thời gian để Hamin ở bên mẹ còn được bao lâu nữa?','Kim Tae-yong',108,'http://res.cloudinary.com/dod2sfnsr/image/upload/c_fill,g_face,h_420,w_280/wpptozenjebpzuiguzo4','2026-03-20','NOW_SHOWING','ĐẾM NGÀY XA MẸ','https://www.youtube.com/watch?v=Dp-3zxsfWbw','2026-04-22 02:50:18.998680'),('5647a4ed-15cb-46e2-b2ec-519938ec40e8','Liên Bỉnh Phát, Tam Triều Dâng, Kiều Oanh, Lê Hải, Mai Cát Vi và một số diễn viên khác','2026-04-22 01:20:48.308697','When a sudden phone scam strikes, Dang Thuc—who once believed he had a stable life in his hands—is pulled into a dangerous spiral of money, family, and trust, where every choice costs not only cash, but also the very people he loves.','Oscar Dương',89,'http://res.cloudinary.com/dod2sfnsr/image/upload/c_fill,g_face,h_420,w_280/nonb9nnlbiisienjf9jz','2026-04-25','COMING_SOON','BẪY TIỀN','https://www.youtube.com/watch?v=oRUSnFHQU2I','2026-04-22 08:54:38.595420'),('747ee971-6f12-46c2-b4dd-1d4d80ef080b','Sukollawat Kanaros, Mario Maurer, Arak Amornsupasiri, Phakhin Khamwilaisak, Mashannoad Suvalmas, Todsapol Maisuk, and Phollawat Manuprasert','2026-04-22 02:15:18.899977','Trong Thế Chiến II, 9 tấn vàng của chính phủ Thái Lan đột ngột bị thất lạc - Châm ngòi cho cuộc truy lùng đẫm máu khắp cả nước. Bốn tên cướp khét tiếng, mỗi người sở hữu một năng lực tà thuật riêng, bị lôi kéo vào trò chơi tử thần. Giữa thời đại mà công lý sụp đổ và người dân không còn nơi nương tựa, một huyền thoại hùng mạnh đã ra đời: Tứ Hổ.','Kongkiat Komesiri',122,'http://res.cloudinary.com/dod2sfnsr/image/upload/c_fill,g_face,h_420,w_280/rdt8virh083a7bts8uje','2026-03-27','NOW_SHOWING','TỨ HỔ ĐẠI NÁO','https://www.youtube.com/watch?v=VTfYsP8N18M','2026-04-22 02:15:18.899977'),('a1866aa2-3619-49e5-a6fb-7a182e1083fc','Dustin Nguyễn, Misthy, Trung Anh, Đinh Y Nhung, Jun Vũ, Hoàng Phi, Hynee, Khoai Vũ','2026-04-22 01:44:02.140273','Hai lễ cưới, một sang trọng sa hoa, một đạm bạc dân dã, đáng lý sẽ được tổ chức đối diện nhau. Rắc rối bắt đầu khi đội ngũ tổ chức của hai lễ cưới phát hiện ra danh sách khách mời của hai bên là giống nhau.','Vũ Hà',113,'http://res.cloudinary.com/dod2sfnsr/image/upload/c_fill,g_face,h_420,w_280/n4x9t33jzhfoa8hjejuq','2026-04-21','NOW_SHOWING','SONG HỶ LÂM NGUY','https://www.youtube.com/watch?v=5EsKEj1u-lM','2026-04-22 01:44:02.140273'),('a7c8b9b5-0717-45a4-941c-3ff58a60a73c','Jon Hamm, Bobby Moynihan, Piper Curda','2026-04-22 01:30:49.283893','Hoppers xoay quanh Mabel, một cô gái yêu động vật, vô tình tiếp cận công nghệ cho phép chuyển ý thức con người vào cơ thể robot động vật. Nhờ đó, Mabel “nhảy” vào thế giới tự nhiên dưới hình dạng một con hải ly và có thể giao tiếp trực tiếp với các loài khác. Trong hành trình này, cô dần khám phá cách động vật nhìn nhận con người, đồng thời phát hiện những mối nguy đang đe dọa môi trường sống của chúng. Tận dụng công nghệ Nhảy, Mabel đã trở thành cầu nối, mang lại cuộc sống cân bằng cho cả con người và động vật.','Daniel Chong',105,'http://res.cloudinary.com/dod2sfnsr/image/upload/c_fill,g_face,h_420,w_280/syubcywgcphsigqhvrhk','2026-04-22','NOW_SHOWING','CÚ NHẢY KỲ DIỆU','https://www.youtube.com/watch?v=PcppouFHoSE','2026-04-22 03:03:42.985789'),('a7db477d-b8bc-40f3-b7fb-b233d15a7a4e','Đoàn Thiên Ân, Khương Lê, NSND Lê Khanh, Huỳnh Phương, Nguyên Thảo, NSND Kim Xuân, Thanh Sơn, Hứa Vĩ Văn, Lâm Vỹ Dạ, Hứa Minh Đạt.','2026-04-22 01:11:34.612487','Năm 1995, khi đang đứng trước một quyết định quan trọng của cuộc đời, Ân bất ngờ bị kéo trở lại quá khứ bởi những bức thư tình chưa từng trao tay. Hành trình tìm gặp Thiên - mối tình đầu từng khắc sâu trong tim - đưa cô về lại thôn xóm Trà Mây năm xưa, nơi những ký ức ngọt ngào xen lẫn tổn thương vẫn chưa hề nguôi ngoai. Trong khoảnh khắc định mệnh khi hai người bất ngờ chạm mặt, những bí mật bị che giấu suốt nhiều năm dần hé lộ, buộc Ân phải đối diện với sự thật và lựa chọn con đường cho riêng mình. “Hẹn Em Ngày Nhật Thực” là câu chuyện tình yêu đầy cảm xúc về những điều chưa nói, về tình yêu vĩnh cửu và câu hỏi day dứt: nếu còn cơ hội, ta có dám tin vào trái tim mình một lần nữa?','Lê Thiện Viễn',118,'http://res.cloudinary.com/dod2sfnsr/image/upload/c_fill,g_face,h_420,w_280/glnn297dqprsvlqejfmm','2026-04-24','COMING_SOON','HẸN EM NGÀY NHẬT THỰC','youtube.com/watch?v=niPGexbd6pM&time_continue=1&source_ve_path=MjM4NTE&embeds_referring_euri=https%3A%2F%2Fwww.cgv.vn%2F','2026-04-22 03:12:22.233677'),('af095d2c-0fa1-4238-876c-44eaa8080f2b','Judy Ongg, CHEN Yi-Han, SUN Shu-May, Amber An, CHUNG Hsin-Ling','2026-04-21 16:16:45.281010','Trong  gian ngột ngạt của một nhà tù nữ, một mầm sống mới đã nảy mầm: một bé gái chào đời giữa tiếng hát mừng sinh nhật và vòng tay của bốn nữ tù nhân. Mỗi người phụ nữ ấy đều mang một bản án và một quá khứ đầy vết sẹo, nhưng sự xuất hiện của đứa trẻ đã trở thành tia sáng duy nhất sưởi ấm tâm hồn họ. Mọi chuyện trở nên xáo trộn khi một tù nhân mới đầy nổi loạn gia nhập nhóm. Từ những va chạm, mâu thuẫn nảy lửa ban đầu, sự hiện diện ngây thơ của bé gái đã dần xóa tan khoảng cách, biến những con người xa lạ thành một gia đình đặc biệt. Hạnh phúc ngắn chẳng được bao lâu khi đứa trẻ được chẩn đoán mắc một căn bệnh hiểm nghèo về mắt, đe dọa sẽ lấy đi ánh sáng vĩnh viễn. Để dành tặng em một kỷ niệm cuối cùng thật trọn vẹn, những người mẹ \"không cùng huyết thống\" đã quyết định thành lập một dàn đồng ca ngay sau song sắt. Dựa trên câu chuyện có thật đầy xúc động, đạo diễn Gavin Lin đã nhào nặn nên một thước phim tâm lý đầy cảm xúc, đan xen khéo léo giữa tiếng cười rộn rã, âm nhạc chữa lành và hành trình tìm lại bản ngã, hướng thiện của những con người từng lầm lỗi.','Gavin LIN',135,'http://res.cloudinary.com/dod2sfnsr/image/upload/c_fill,g_face,h_420,w_280/efkgmwqfiqgwawgcvooq','2026-04-21','NOW_SHOWING','ÁNH DƯƠNG CỦA MẸ','https://youtu.be/ZMfDN8uzTj4?si=n1ZPmgWNHT2-iH6G','2026-04-22 01:48:19.828894'),('af9dfa83-0c83-4f9d-84ca-aaa6ddf976c3','Suet-Ying Chung; Hiu-Tung Choi; Louis Cheung','2026-04-22 01:54:42.978435','Lấy bối cảnh tại Cõi Ngoại – cõi trung gian giữa cái chết và sự tái sinh, VÙNG ĐẤT LUÂN HỒI kể về hành trình xuyên suốt ngàn năm của Tiểu Quỷ - kẻ mang nhiệm vụ dẫn dắt các linh hồn để giúp họ buông bỏ ký ức và cảm xúc còn sót lại từ kiếp trước để bước vào vòng luân hồi.','Tommy Kai Chung Ng',110,'http://res.cloudinary.com/dod2sfnsr/image/upload/c_fill,g_face,h_420,w_280/fcigurc43okef9cxp4if','2026-03-27','NOW_SHOWING','VÙNG ĐẤT LUÂN HỒI','https://www.youtube.com/watch?v=51ibUmoe6Agv','2026-04-22 01:54:42.978435'),('b545bc47-cf0e-4a3f-9172-99b35609c00d','Somphol Rungphanit, Sarika Sartsilpsupa, Chatchai Plengpanich','2026-04-22 01:52:44.587395','Petch là một tay súng đánh thuê, người đã dành phần lớn cuộc đời sống giữa thế giới bạo lực, nơi những phi vụ đẫm máu diễn ra như một phần công việc thường nhật. Sau nhiều năm lún sâu vào tội lỗi, Petch bắt đầu khao khát rời bỏ con đường cũ để tìm lại tự do và một cuộc sống bình thường. Thế nhưng quá khứ không dễ dàng buông tha anh. Khi những người thân cận bị cuốn vào cuộc thanh trừng giữa các băng nhóm, Petch buộc phải quay lại thế giới mà anh từng cố gắng trốn chạy. Anh chấp nhận thực hiện một nhiệm vụ cuối cùng đầy nguy hiểm, với hy vọng có thể xóa bỏ mọi ân oán trong quá khứ. Nhưng cũng từ đây, Petch bị đẩy vào cuộc đối đầu nghẹt thở với những thế lực từng tạo nên anh. Trong trận chiến sinh tử ấy, mỗi viên đạn đều mang theo cái giá phải trả, và chỉ một sai lầm cũng có thể khiến anh đánh đổi bằng chính mạng sống của mình.v','Put Puttipong Nakthong',113,'http://res.cloudinary.com/dod2sfnsr/image/upload/c_fill,g_face,h_420,w_280/kqvyllzms4jdjouqukox','2026-04-03','NOW_SHOWING','PHI VỤ CUỐI CÙNG','https://www.youtube.com/watch?v=RvAlik264To','2026-04-22 02:50:27.266789'),('bb8569a9-2904-4b74-996a-f7a9ca69570e','Mudit Gupta, Janne Formoe, Torstein Bae, Stig Henrik Hoff, Kåre Conradi, Anne Marit Jacobsen, Olivia Augusta Røv Magelssen, Dennis Storhøi, và Silje Hagrim Dahl','2026-04-22 01:47:07.242870','Bộ phim kể về Rufus, một chú rắn biển nhỏ sống trên một hòn đảo bí mật cùng các sinh vật biển huyền bí. Không giống những sinh vật khác, Rufus không thể bơi, điều này khiến cậu luôn bị xem là khác biệt và gặp nhiều khó khăn trong cuộc sống. Hòn đảo nơi Rufus sinh sống được bảo vệ bởi chú Ludvig (nửa rồng nửa rắn), người có khả năng che giấu sự tồn tại của hòn đảo khỏi con người. Khi Ludvig mất đi năng lực bảo vệ, hòn đảo đứng trước nguy cơ bị loài người phát hiện. Trong tình thế đó, Rufus buộc phải đối mặt với nỗi sợ lớn nhất của mình và tìm cách vượt qua giới hạn bản thân là học bơi để bảo vệ gia đình, bạn bè và ngôi nhà mà cậu yêu quý.','Endre Skandfer',82,'http://res.cloudinary.com/dod2sfnsr/image/upload/c_fill,g_face,h_420,w_280/pei5jcyzwng9dnxzcocs','2026-04-17','NOW_SHOWING','RUFUS: THỦY QUÁI HỌC BƠI','https://www.youtube.com/watch?v=pW0_k72AP8c','2026-04-22 01:47:07.242870'),('bc0efc94-f0c5-4b22-b340-4169eef2836a','Chris Pratt, Anya Taylor-Joy, Charlie Day, Jack Black, Keegan-Michael Key, Benny Safdie, Kevin Michael Richardson và Brie Larson.','2026-04-21 16:57:48.586970','Phim Super Mario Thiên Hà là một bộ phim hoạt hình được lấy bối cảnh trong thế giới của Anh Em Super Mario và là phần tiếp theo của Phim Anh Em Super Mario – tác phẩm ra mắt năm 2023 và đạt doanh thu hơn 1,3 tỷ đô la trên toàn cầu. Cả hai bộ phim Phim Anh Em Super Mario (2023) và Phim Super Mario Thiên Hà đều do Chris Meledandri (hãng Illumination) và Shigeru Miyamoto (từ Nintendo) đồng sản xuất.\n','Aaron Horvath, Michael Jelenic',99,'http://res.cloudinary.com/dod2sfnsr/image/upload/c_fill,g_face,h_420,w_280/bxof1gmpnxuxgyzafyor','2026-04-08','NOW_SHOWING','PHIM SUPER MARIO THIÊN HÀ','https://www.youtube.com/watch?v=sKGBkP3kNvM','2026-04-21 16:58:35.734040'),('bd93aa24-482e-4c5d-9432-5c7a167168d2','Samara Weaving, Kathryn Newton, Sarah Michelle Gellar, Shawn Hatosy, Néstor Carbonell, David Cronenberg, Elijah Wood, Kevin Durand, Olivia Cheng, Varun Saranga, Daniel Beirne','2026-04-22 01:34:26.045377','Chỉ ít phút sau khi sống sót qua cuộc tấn công từ gia tộc Le Domas, Grace (Samara Weaving) phát hiện mình đã bước sang cấp độ tiếp theo của trò chơi ác mộng - và lần này, cô có người em gái xa cách Faith (Kathryn Newton) đồng hành. Grace chỉ có một cơ hội để sống sót, bảo vệ em gái và giành lấy Vị Trí Tối Cao của Hội Đồng - thế lực kiểm soát cả thế giới. Bốn gia tộc đối địch đang săn lùng cô vì chiếc ngai vàng, và kẻ chiến thắng sẽ nắm quyền lực tuyệt đối.','Matt Bettinelli-Olpin & Tyler Gillett',107,'http://res.cloudinary.com/dod2sfnsr/image/upload/c_fill,g_face,h_420,w_280/t76gzhgtfh2c0ppuwptt','2026-04-27','COMING_SOON','TRÒ CHƠI CỦA QUỶ 2','https://www.youtube.com/watch?v=5Sfi_Oe1Bdk','2026-04-22 01:34:26.045377'),('c2ba4fa5-cb01-4c39-aa87-fbcd448cb96c','Kiều Minh Tuấn, Nina Nutthacha Padovan, Diệp Bảo Ngọc, Đoàn Minh Anh, NSƯT Hạnh Thuý,...','2026-04-21 15:01:12.665226','Phí Phông, loài quỷ khát máu trong truyền thuyết dân gian của đồng bào miền núi gây ám ảnh bao đời nay. Phim xoay quanh Còn (Kiều Minh Tuấn) và Dương (Minh Anh), hai pháp sư tập sự lên núi cứu người mẹ đang bị lời nguyền Phí Phông đánh gục. Cùng lúc đó, trong bản sâu cũng xảy ra nhiều cái chết ghê rợn. Mọi nghi ngờ đổ dồn về hai mẹ con Mon (Diệp Bảo Ngọc) và Lua (Nina Nutthacha), những người mang đặc tính y hệt Phí Phông. Thế nhưng, vẫn còn những bí mật động trời bị chôn vùi trong chốn rừng thiêng nước độc, cuốn hai anh em Còn và Dương vào cuộc truy lùng “Phí Phông” không hồi kết.','Đỗ Quốc Trung',120,'http://res.cloudinary.com/dod2sfnsr/image/upload/c_fill,g_face,h_420,w_280/g7sdfetqgptr8bhwyu21','2026-04-14','NOW_SHOWING','PHÍ PHÔNG: QUỶ MÁU RỪNG THIÊNG','https://youtu.be/M39AbAEVGKo?si=rnV9N1WwlzSTOewD','2026-04-22 01:23:54.202040'),('c9cdeac6-a000-4925-b1b9-a77c992f94f6','Dakota Fanning, Teri Hatcher, Keith David, Jennifer Saunders','2026-04-22 02:03:25.000835','Khi gia đình chuyển đến một lâu đài cổ, Coraline vô tình mở ra cánh cửa dẫn tới một thế giới song song, nơi mọi thứ rực rỡ và hoàn hảo một cách đáng ngờ. Nhưng càng đắm mình trong sự “hoàn hảo” ấy, cô càng nhận ra phía sau lớp vỏ dịu dàng là một vực sâu nguy hiểm đang chực chờ nuốt chửng tất cả. Thế giới kia không phải phép màu, mà là chiếc bẫy được giăng bằng những bí mật đen tối. Để cứu gia đình và chính mình, Coraline buộc phải đối diện với thực thể tà ác đang ẩn sau vẻ ngoài rực rỡ và đôi mắt trống rỗng vô hồn.','Henry Selick',101,'http://res.cloudinary.com/dod2sfnsr/image/upload/c_fill,g_face,h_420,w_280/pciedp3oxgecywbzz8rr','2026-03-27','NOW_SHOWING','CÔ BÉ CORALINE','https://www.youtube.com/watch?v=CBP1w2y-JRM','2026-04-22 02:03:48.614070'),('ccccb510-121a-4cb4-b6d5-3232537430d7','Điền','2026-04-22 08:54:05.385093','Đánh nhau với Thanos','Điền',180,'http://res.cloudinary.com/dod2sfnsr/image/upload/c_fill,g_face,h_420,w_280/brdtk66j592picnvhnvk','2026-04-21','ENDED','Avenger: End Game','https://www.youtube.com/watch?v=8gcRTMr-rlg&time_continue=0&source_ve_path=NzY3NTg&embeds_referring_euri=https%3A%2F%2Fwww.bing.com%2F&embeds_referring_origin=https%3A%2F%2Fwww.bing.com','2026-04-22 09:13:01.342912'),('cd70f637-07d4-4502-a832-dc8a88b64ffa','Ryan Gosling, Liz Kingsman, Milana Vayntrub, Sandra Hüller','2026-04-22 01:28:31.192036','Ryland Grace một giáo viên khoa học nhận ra anh chính là hy vọng cuối cùng của Trái Đất. Nhiệm vụ của anh: cứu lấy Mặt Trời khỏi một sinh thể bí ẩn đang hút cạn năng lượng ánh sáng, đẩy cả hệ Mặt Trời vào bóng tối vĩnh viễn. Nếu thất bại, sự sống trên Trái Đất sẽ lụi tàn theo ánh sáng cuối cùng của mặt trời. Giữa không gian vũ trụ cô độc và áp lực của thời gian đang cạn dần, mọi phép tính, mọi quyết định của anh đều gánh trên vai số phận của toàn nhân loại. Nhưng trong hành trình tưởng chừng chỉ có một mình giữa khoảng không vô tận ấy, một tình bạn bất ngờ với một sinh vật ngoài hành tinh đã xuất hiện. Và có lẽ, để cứu Trái Đất, anh sẽ không phải chiến đấu một mình.','Phil Lord, Christopher Miller',157,'http://res.cloudinary.com/dod2sfnsr/image/upload/c_fill,g_face,h_420,w_280/owjghcbabm2hyruy0pew','2026-06-20','COMING_SOON','THOÁT KHỎI TẬN THẾ','https://www.youtube.com/watch?v=LQ9KHDpA9vI','2026-04-22 03:11:42.729205'),('d1ee9536-0deb-48b3-bdc1-289d94f16548','Mos Panuwat Sopradit, Diana Flipo, Bank Mondop Heamtan, Ploypaphas Fonkaewsiwaporn, Thiti Srinual','2026-04-22 01:17:34.165402','Khi ngôi nhà mới được xây trên mảnh đất của thần linh, gia đình Joi đã phải lập tức đối mặt với cơn thịnh nộ của Phi Ta Khon (Quỷ Đội Lốt Người). Để giải cứu chính mình và em gái khỏi lời nguyền nghiệt ngã, Joi quyết tâm lật mở sự thật. Thế nhưng, đằng sau chiếc mặt nạ quỷ lại là một bí mật đen tối mà cậu không bao giờ ngờ tới.','Puwadon Naosopa',99,'http://res.cloudinary.com/dod2sfnsr/image/upload/c_fill,g_face,h_420,w_280/sdxeiom8oj7ihajscfh9','2026-04-03','NOW_SHOWING','TAKHON: QUỶ ĐỘI LỐT','https://www.youtube.com/watch?v=g6BumUNQl1U','2026-04-22 09:15:32.998898'),('e1726095-9c4b-4e1b-be48-2a6842ad6be4','Jack Reynor, Laia Costa, May Calamawy','2026-04-22 01:13:50.547434','Ngay sau sự trở lại và thành công vang dội của bộ phim EVIL DEAD RISE, biên kịch/đạo diễn Lee Cronin tiếp tục khai thác một trong những câu chuyện kinh dị kinh điển nhất mọi thời đại với phiên bản đầy kịch tính: MỘT BỘ PHIM CỦA LEE CRONIN: XÁC ƯỚP. Phim khai thác câu chuyện về cô con gái nhỏ của một nhà báo biến mất không dấu vết trong sa mạc. Tám năm sau, gia đình đã tan vỡ bỗng bàng hoàng khi cô bé trở về, và điều lẽ ra phải là một cuộc hội ngộ hạnh phúc lại biến thành một cơn ác mộng kinh hoàng.','Lee Cronin',133,'http://res.cloudinary.com/dod2sfnsr/image/upload/c_fill,g_face,h_420,w_280/ixo5pdqzrhanotwbq0jd','2026-04-01','NOW_SHOWING','MỘT BỘ PHIM CỦA LEE CRONIN: XÁC ƯỚP','youtube.com/watch?v=MCYebV4Dpww&time_continue=0&source_ve_path=MjM4NTE&embeds_referring_euri=https%3A%2F%2Fwww.cgv.vn%2F','2026-04-22 01:47:46.745794'),('e89e6a46-c2fc-41c3-b10e-686e3a0bffe9','Han So-hee, Jeon Jong-seo, Kim Shin-rock','2026-04-22 02:13:11.603772','','Hwan Lee',109,'http://res.cloudinary.com/dod2sfnsr/image/upload/c_fill,g_face,h_420,w_280/nof2r7slku94n2dx6hoy','2026-03-27','NOW_SHOWING','PROJECT Y: GÁI NGOAN ĐỔI ĐỜI','https://www.youtube.com/watch?v=PNTqUudPD18','2026-04-22 02:13:11.603772'),('f350b948-3a88-4dba-a2c5-356fcb793819','Yoo Hai-jin, Park Ji-hoon, Yoo Ji-tae, Jeon Mi-do','2026-04-22 01:22:56.290961','Lấy mốc năm 1457 dưới triều đại Joseon, Dưới Bóng Điện Hạ khắc họa số phận nghiệt ngã của vua Danjong - vị quân vương thứ sáu của triều đại (Park Ji-hoon thủ vai). Lên ngôi khi tuổi đời còn non trẻ, Danjong nhanh chóng trở thành quân cờ trong vòng xoáy quyền lực tàn khốc. Bị chính người chú lật đổ, phế truất và đày đến vùng Cheongnyeongpo heo hút, cuộc đời của vị vua trẻ rẽ sang một ngã rẽ đầy u uất. Tại chốn lưu đày, ông gặp trưởng làng Eom Heung Do (Yoo Hai-jin thủ vai) - người đã chủ động biến ngôi làng nghèo thành nơi giam giữ nhà vua, đổi lại hy vọng cứu vãn sinh kế cho dân làng. Từ hai thân phận tưởng chừng đối lập, một cựu đế vương và một thường dân, bộ phim dần hé mở mối liên kết lặng lẽ nhưng sâu sắc - nơi lòng trung thành, sự che chở âm thầm và những phận người nhỏ bé cùng trôi dạt giữa cơn sóng lớn của lịch sử.','Chang Hang-jun',117,'http://res.cloudinary.com/dod2sfnsr/image/upload/c_fill,g_face,h_420,w_280/xso5p5bzwbk4i9qwmqe8','2026-04-02','NOW_SHOWING','DƯỚI BÓNG ĐIỆN HẠ','https://www.youtube.com/watch?v=aPsEOR-WK6U','2026-04-22 01:47:54.017192');
